[package]
name        = "paigasus-helikon"
description = "Paigasus AI SDK — facade crate. Re-exports core plus feature-gated providers and runtimes."
version                = "0.4.11"
edition.workspace      = true
rust-version.workspace = true
authors.workspace      = true
license.workspace      = true
repository.workspace   = true
homepage.workspace     = true
keywords.workspace     = true
categories.workspace   = true

[dependencies]
paigasus-helikon-core                = { workspace = true }
paigasus-helikon-macros              = { workspace = true, optional = true }
paigasus-helikon-providers-openai    = { workspace = true, optional = true }
paigasus-helikon-providers-anthropic = { workspace = true, optional = true }
paigasus-helikon-mcp                 = { workspace = true, optional = true }
paigasus-helikon-tools               = { workspace = true, optional = true }
paigasus-helikon-runtime-tokio       = { workspace = true, optional = true }
paigasus-helikon-runtime-axum        = { workspace = true, optional = true }
paigasus-helikon-runtime-temporal    = { workspace = true, optional = true }
paigasus-helikon-runtime-agentcore   = { workspace = true, optional = true }
paigasus-helikon-sessions-sqlite     = { workspace = true, optional = true }
paigasus-helikon-evals               = { workspace = true, optional = true }
paigasus-helikon-providers-bedrock   = { workspace = true, optional = true }
paigasus-helikon-providers-gemini    = { workspace = true, optional = true }

[features]
default            = []
macros             = ["dep:paigasus-helikon-macros"]
openai             = ["dep:paigasus-helikon-providers-openai"]
providers-openai   = ["dep:paigasus-helikon-providers-openai"]
anthropic          = ["dep:paigasus-helikon-providers-anthropic"]
mcp                = ["dep:paigasus-helikon-mcp"]
tools              = ["dep:paigasus-helikon-tools"]
tools-web          = ["tools", "paigasus-helikon-tools/web"]
tools-os-sandbox   = ["tools", "paigasus-helikon-tools/os-sandbox"]
tools-microvm      = ["tools", "paigasus-helikon-tools/microvm"]
evals              = ["dep:paigasus-helikon-evals"]
runtime-tokio      = ["dep:paigasus-helikon-runtime-tokio"]
runtime-axum       = ["dep:paigasus-helikon-runtime-axum"]
runtime-temporal   = ["dep:paigasus-helikon-runtime-temporal"]
runtime-agentcore  = ["dep:paigasus-helikon-runtime-agentcore"]
sessions-sqlite    = ["dep:paigasus-helikon-sessions-sqlite"]
bedrock            = ["dep:paigasus-helikon-providers-bedrock"]
gemini             = ["dep:paigasus-helikon-providers-gemini"]

[dev-dependencies]
# Installs git hooks from .cargo-husky/hooks/ when this crate's
# dev-deps are realized (e.g. `cargo test -p paigasus-helikon --no-run`).
# See SMA-335 design doc §4.
cargo-husky = { version = "1", default-features = false, features = ["user-hooks"] }
# Trybuild for the facade_only_consumer UI test (SMA-385 §5.5 — moved
# here from paigasus-helikon-macros to break the publish-time dep cycle).
# serde_json is required because the #[tool] macro expansion emits
# `::serde_json::…` paths directly (see -macros/src/expand.rs).
trybuild    = { workspace = true }
schemars    = { workspace = true }
serde       = { workspace = true }
serde_json  = { workspace = true }
# Required by the structured_output example (SMA-323).
tokio       = { workspace = true, features = ["macros", "rt-multi-thread"] }
anyhow      = { workspace = true }
# SMA-322 — OTel export stack for the langfuse_tracing example + otel_spans test.
async-trait           = { workspace = true }
futures-core          = { workspace = true }
futures-util          = { workspace = true }
tracing               = { workspace = true }
tracing-subscriber    = { workspace = true }
tracing-opentelemetry = { workspace = true }
opentelemetry         = { workspace = true }
opentelemetry_sdk     = { workspace = true }
opentelemetry-otlp    = { workspace = true }
base64                = { workspace = true }

[[example]]
name              = "structured_output"
required-features = ["anthropic"]

[[example]]
name              = "budget_assistant_openai"
required-features = ["openai", "macros"]

[[example]]
name              = "budget_assistant_anthropic"
required-features = ["anthropic", "macros"]

[[example]]
name              = "streaming_console"
required-features = ["openai"]

[[example]]
name              = "langfuse_tracing"
required-features = ["runtime-tokio"]

[[example]]
name              = "multi_agent_triage"
required-features = ["openai"]

[[bench]]
name    = "tool_dispatch"
harness = false
# A benchmark, not a test: `test = false` keeps `cargo test` from building and
# running the timing loop, and keeps it out of the `test (…, 1.85)` CI job.
test    = false

[lints]
workspace = true

#![doc = include_str!("../README.md")]

/// Trait surface and concrete types shared by every Paigasus Helikon crate. Always available.
pub use paigasus_helikon_core as core;

/// Proc macros for the SDK. Enabled via the `macros` feature.
#[cfg(feature = "macros")]
pub use paigasus_helikon_macros as macros;

/// `#[tool]` attribute macro — enabled via the `macros` feature.
#[cfg(feature = "macros")]
pub use paigasus_helikon_macros::tool;

/// `tools!` function-like macro — enabled via the `macros` feature.
#[cfg(feature = "macros")]
pub use paigasus_helikon_macros::tools;

/// OpenAI provider. Enabled via the `openai` feature.
#[cfg(feature = "openai")]
pub use paigasus_helikon_providers_openai as openai;

/// OpenAI provider — [`paigasus_helikon_providers_openai`]. Enabled via the `providers-openai` feature.
#[cfg(feature = "providers-openai")]
pub use paigasus_helikon_providers_openai as providers_openai;

/// Anthropic provider. Enabled via the `anthropic` feature.
#[cfg(feature = "anthropic")]
pub use paigasus_helikon_providers_anthropic as anthropic;

/// MCP client and server integration. Enabled via the `mcp` feature.
#[cfg(feature = "mcp")]
pub use paigasus_helikon_mcp as mcp;

/// Sandboxed Read/Write/Edit/Bash tools. Enabled via the `tools` feature; the
/// `WebFetch`/`WebSearch` network tools additionally require `tools-web`.
#[cfg(feature = "tools")]
pub use paigasus_helikon_tools as tools;

/// Evaluation harness. Enabled via the `evals` feature.
#[cfg(feature = "evals")]
pub use paigasus_helikon_evals as evals;

/// Default ephemeral Tokio runner. Enabled via the `runtime-tokio` feature.
#[cfg(feature = "runtime-tokio")]
pub use paigasus_helikon_runtime_tokio as runtime_tokio;

/// Self-hosted Axum runtime. Enabled via the `runtime-axum` feature.
#[cfg(feature = "runtime-axum")]
pub use paigasus_helikon_runtime_axum as runtime_axum;

/// Temporal-backed durable runtime. Enabled via the `runtime-temporal` feature.
#[cfg(feature = "runtime-temporal")]
pub use paigasus_helikon_runtime_temporal as runtime_temporal;

/// AWS Bedrock AgentCore runtime. Enabled via the `runtime-agentcore` feature.
#[cfg(feature = "runtime-agentcore")]
pub use paigasus_helikon_runtime_agentcore as runtime_agentcore;

/// SQLite-backed `Session` backend. Enabled via the `sessions-sqlite` feature.
#[cfg(feature = "sessions-sqlite")]
pub use paigasus_helikon_sessions_sqlite as sessions_sqlite;

/// Bedrock provider (Converse model). Enabled via the `bedrock` feature.
/// Distinct from `runtime-agentcore` (the Bedrock AgentCore runtime).
#[cfg(feature = "bedrock")]
pub use paigasus_helikon_providers_bedrock as bedrock;

/// Google Gemini provider (Developer API + Vertex). Enabled via the `gemini` feature.
#[cfg(feature = "gemini")]
pub use paigasus_helikon_providers_gemini as gemini;

/// JSON Schema helpers.
pub mod schema {
    /// OpenAI/JSON-Schema strict-mode normalizer — see
    /// [`paigasus_helikon_core::schema::strict`].
    pub use paigasus_helikon_core::schema::strict;
}

