1	//! The [`Session`] trait and its carrier types.
2	//!
3	//! `Session` models conversation persistence as an **append-only event
4	//! log**, not a flat message list. The event-log shape gives evals
5	//! (deterministic replay), durability (Temporal/Restate-style event
6	//! sourcing), and an audit trail for regulated deployments.
7	
8	use async_trait::async_trait;
9	use jiff::Timestamp;
10	use serde::{Deserialize, Serialize};
11	
12	use crate::{AgentEvent, ContentPart, Item};
13	
14	/// Conversation persistence as an append-only event log.
15	///
16	/// See the *Sessions* concept page for the rationale.
17	///
18	/// # Example
19	///
20	/// ```
21	/// use async_trait::async_trait;
22	/// use paigasus_helikon_core::{
23	///     ConversationSnapshot, SequenceId, Session, SessionError, SessionEvent,
24	/// };
25	///
26	/// struct MemorySession;
27	///
28	/// #[async_trait]
29	/// impl Session for MemorySession {
30	///     async fn append(
31	///         &self,
32	///         _events: &[SessionEvent],
33	///     ) -> Result<(), SessionError> {
34	///         Ok(())
35	///     }
36	///
37	///     async fn events(
38	///         &self,
39	///         _since: Option<SequenceId>,
40	///     ) -> Result<Vec<SessionEvent>, SessionError> {
41	///         Ok(Vec::new())
42	///     }
43	///
44	///     async fn snapshot(&self) -> Result<ConversationSnapshot, SessionError> {
45	///         Ok(ConversationSnapshot::default())
46	///     }
47	/// }
48	/// ```
49	#[async_trait]
50	pub trait Session: Send + Sync {
51	    /// Append events to the log.
52	    async fn append(&self, events: &[SessionEvent]) -> Result<(), SessionError>;
53	
54	    /// Read events from the log, optionally only those after `since`.
55	    async fn events(&self, since: Option<SequenceId>) -> Result<Vec<SessionEvent>, SessionError>;
56	
57	    /// Compute (or read) a [`ConversationSnapshot`] projection of the log.
58	    async fn snapshot(&self) -> Result<ConversationSnapshot, SessionError>;
59	}
60	
61	/// One entry in the conversation event log.
62	///
63	/// `UserMessage` / `AssistantMessage` / `ToolReturned` carry
64	/// `Vec<ContentPart>` directly (not `Item`) because the SessionEvent
65	/// variant *is* the role — wrapping `Item::UserMessage` inside
66	/// `SessionEvent::UserMessage` would double-tag.
67	#[derive(Debug, Clone, Serialize, Deserialize)]
68	#[serde(tag = "type", rename_all = "snake_case")]
69	#[non_exhaustive]
70	pub enum SessionEvent {
71	    /// A user-authored message.
72	    ///
73	    /// The enum is marked `#[non_exhaustive]` at the enum level (not per
74	    /// variant) so downstream tests and fixtures can construct variants
75	    /// by struct-init to pin a deterministic `ts`. Don't tighten this to
76	    /// per-variant `#[non_exhaustive]`.
77	    UserMessage {
78	        /// Content blocks of the message.
79	        content: Vec<ContentPart>,
80	        /// Wall-clock instant the event was recorded. UTC, nanosecond precision.
81	        ts: Timestamp,
82	    },
83	    /// An assistant-authored message attributed to a named agent.
84	    AssistantMessage {
85	        /// Content blocks of the message.
86	        content: Vec<ContentPart>,
87	        /// Name of the emitting [`crate::Agent`]. `String` (not `Option`)
88	        /// because the runner always knows which agent emitted when
89	        /// appending to the log.
90	        agent: String,
91	        /// Wall-clock instant the event was recorded. UTC, nanosecond precision.
92	        ts: Timestamp,
93	    },
94	    /// The runner invoked a tool.
95	    ToolCalled {
96	        /// Provider-assigned call identifier.
97	        call_id: String,
98	        /// Tool name.
99	        name: String,
100	        /// JSON arguments.
101	        args: serde_json::Value,
102	        /// Wall-clock instant the event was recorded. UTC, nanosecond precision.
103	        ts: Timestamp,
104	    },
105	    /// The tool returned.
106	    ToolReturned {
107	        /// Matching call identifier.
108	        call_id: String,
109	        /// Content blocks of the tool's output (Anthropic permits
110	        /// text + image inside a tool result).
111	        content: Vec<ContentPart>,
112	        /// Wall-clock instant the event was recorded. UTC, nanosecond precision.
113	        ts: Timestamp,
114	    },
115	    /// Control transferred from one agent to another.
116	    HandoffOccurred {
117	        /// Outgoing agent name.
118	        from: String,
119	        /// Incoming agent name.
120	        to: String,
121	        /// Wall-clock instant the event was recorded. UTC, nanosecond precision.
122	        ts: Timestamp,
123	    },
124	    /// Older events were compacted into a summary.
125	    ///
126	    /// **Provider-translator caveat:** [`project`] renders this as
127	    /// [`Item::System`]. Both shipped provider translators reshape
128	    /// `Item::System`: Anthropic hoists every system block into the
129	    /// top-level `system` field, and OpenAI concatenates multiple system
130	    /// blocks into one at the top of the conversation. The "summary
131	    /// replaces turns 1..N at this position" semantic is therefore
132	    /// observation-only in the event log; the model sees the summary text
133	    /// but as a top-level system instruction, not a positional cutover.
134	    Compacted {
135	        /// LLM-produced summary.
136	        summary: String,
137	        /// Number of events the summary replaces. `u64` (not `usize`)
138	        /// because the value is serialized into the persisted log — a
139	        /// 32-bit consumer must read what a 64-bit producer wrote.
140	        original_count: u64,
141	        /// Wall-clock instant the event was recorded. UTC, nanosecond precision.
142	        ts: Timestamp,
143	    },
144	}
145	
146	impl SessionEvent {
147	    /// Construct a [`SessionEvent::UserMessage`] with `ts = Timestamp::now()`.
148	    pub fn user_message(content: Vec<ContentPart>) -> Self {
149	        Self::UserMessage {
150	            content,
151	            ts: Timestamp::now(),
152	        }
153	    }
154	
155	    /// Construct a [`SessionEvent::AssistantMessage`] with `ts = Timestamp::now()`.
156	    pub fn assistant_message(content: Vec<ContentPart>, agent: impl Into<String>) -> Self {
157	        Self::AssistantMessage {
158	            content,
159	            agent: agent.into(),
160	            ts: Timestamp::now(),
161	        }
162	    }
163	
164	    /// Construct a [`SessionEvent::ToolCalled`] with `ts = Timestamp::now()`.
165	    pub fn tool_called(
166	        call_id: impl Into<String>,
167	        name: impl Into<String>,
168	        args: serde_json::Value,
169	    ) -> Self {
170	        Self::ToolCalled {
171	            call_id: call_id.into(),
172	            name: name.into(),
173	            args,
174	            ts: Timestamp::now(),
175	        }
176	    }
177	
178	    /// Construct a [`SessionEvent::ToolReturned`] with `ts = Timestamp::now()`.
179	    pub fn tool_returned(call_id: impl Into<String>, content: Vec<ContentPart>) -> Self {
180	        Self::ToolReturned {
181	            call_id: call_id.into(),
182	            content,
183	            ts: Timestamp::now(),
184	        }
185	    }
186	
187	    /// Construct a [`SessionEvent::HandoffOccurred`] with `ts = Timestamp::now()`.
188	    pub fn handoff_occurred(from: impl Into<String>, to: impl Into<String>) -> Self {
189	        Self::HandoffOccurred {
190	            from: from.into(),
191	            to: to.into(),
192	            ts: Timestamp::now(),
193	        }
194	    }
195	
196	    /// Construct a [`SessionEvent::Compacted`] with `ts = Timestamp::now()`.
197	    pub fn compacted(summary: impl Into<String>, original_count: u64) -> Self {
198	        Self::Compacted {
199	            summary: summary.into(),
200	            original_count,
201	            ts: Timestamp::now(),
202	        }
203	    }
204	}
205	
206	/// In-memory [`Session`] backend backed by a `std::sync::Mutex<Vec<_>>`.
207	///
208	/// Suitable for tests and ephemeral runs. One instance is one session by
209	/// construction — there is no `session_id`. For persistent or multi-session
210	/// storage, see `paigasus-helikon-sessions-sqlite`.
211	///
212	/// Lock poisoning panics (`expect`): if a panic occurred inside a critical
213	/// section, an invariant is already broken. Fail loud.
214	///
215	/// **Platform assumption:** [`MemorySession::events`] panics on 32-bit
216	/// targets if a single session accumulates more than `u32::MAX` events
217	/// (the `SequenceId` → `usize` conversion via [`usize::try_from`] then
218	/// fails). Sessions of that size are unreachable in practice; the panic
219	/// is intentional rather than a typed `SessionError` so the failure
220	/// surfaces immediately rather than being silently treated as a backend
221	/// error.
222	#[derive(Debug, Default)]
223	pub struct MemorySession {
224	    inner: std::sync::Mutex<Vec<SessionEvent>>,
225	}
226	
227	impl MemorySession {
228	    /// Create an empty [`MemorySession`].
229	    pub fn new() -> Self {
230	        Self::default()
231	    }
232	}
233	
234	#[async_trait]
235	impl Session for MemorySession {
236	    async fn append(&self, events: &[SessionEvent]) -> Result<(), SessionError> {
237	        let mut guard = self.inner.lock().expect("MemorySession mutex poisoned");
238	        guard.extend_from_slice(events);
239	        Ok(())
240	    }
241	
242	    async fn events(&self, since: Option<SequenceId>) -> Result<Vec<SessionEvent>, SessionError> {
243	        let guard = self.inner.lock().expect("MemorySession mutex poisoned");
244	        // `since` is *exclusive* — matches the existing trait doc ("those
245	        // after `since`"). `try_from` ensures 32-bit targets fail loudly
246	        // instead of wrapping past `u32::MAX`; `saturating_add` then guards
247	        // the +1 against the SequenceId(u64::MAX) edge case on 64-bit where
248	        // usize::MAX + 1 would overflow. Both branches are unreachable in
249	        // practice; the saturated result clamps `start` so the slice below
250	        // returns an empty Vec rather than wrapping.
251	        let start = match since {
252	            Some(s) => usize::try_from(s.0)
253	                .expect("SequenceId exceeds platform usize")
254	                .saturating_add(1),
255	            None => 0,
256	        };
257	        Ok(guard.get(start..).unwrap_or(&[]).to_vec())
258	    }
259	
260	    async fn snapshot(&self) -> Result<ConversationSnapshot, SessionError> {
261	        let events = self.events(None).await?;
262	        Ok(project(&events))
263	    }
264	}
265	
266	/// Project an append-only [`SessionEvent`] log into a [`ConversationSnapshot`]
267	/// — the canonical message-list view that providers consume.
268	///
269	/// **Provider-translator caveat:** `Compacted` events render as
270	/// [`Item::System`]. Both shipped provider translators (SMA-316 OpenAI,
271	/// SMA-317 Anthropic) reshape system messages — Anthropic hoists every
272	/// `Item::System` into the top-level `system` field; OpenAI concatenates
273	/// multiple system blocks into one at the top of the conversation. The
274	/// "summary replaces turns 1..N at this position" semantic is therefore
275	/// observation-only in the event log; the model sees the summary text but
276	/// as a top-level system instruction, not a positional cutover.
277	pub fn project(events: &[SessionEvent]) -> ConversationSnapshot {
278	    let mut messages: Vec<Item> = Vec::new();
279	    // Parallel vec: contributions[i] = number of messages event i produced.
280	    // Needed because Compacted has to undo the message yield of the previous
281	    // N events, and yield varies per variant (HandoffOccurred = 0, others = 1).
282	    let mut contributions: Vec<usize> = Vec::new();
283	
284	    for ev in events {
285	        match ev {
286	            SessionEvent::UserMessage { content, .. } => {
287	                messages.push(Item::UserMessage {
288	                    content: content.clone(),
289	                });
290	                contributions.push(1);
291	            }
292	            SessionEvent::AssistantMessage { content, agent, .. } => {
293	                messages.push(Item::AssistantMessage {
294	                    content: content.clone(),
295	                    agent: Some(agent.clone()),
296	                });
297	                contributions.push(1);
298	            }
299	            SessionEvent::ToolCalled {
300	                call_id,
301	                name,
302	                args,
303	                ..
304	            } => {
305	                messages.push(Item::ToolCall {
306	                    call_id: call_id.clone(),
307	                    name: name.clone(),
308	                    args: args.clone(),
309	                });
310	                contributions.push(1);
311	            }
312	            SessionEvent::ToolReturned {
313	                call_id, content, ..
314	            } => {
315	                messages.push(Item::ToolResult {
316	                    call_id: call_id.clone(),
317	                    content: content.clone(),
318	                });
319	                contributions.push(1);
320	            }
321	            SessionEvent::HandoffOccurred { .. } => {
322	                // Audit-only event; no message produced.
323	                contributions.push(0);
324	            }
325	            SessionEvent::Compacted {
326	                summary,
327	                original_count,
328	                ..
329	            } => {
330	                let n = usize::try_from(*original_count).unwrap_or(usize::MAX);
331	                if n == 0 {
332	                    tracing::warn!(
333	                        "Compacted event with original_count = 0; emitting summary as a system message without compacting any history (likely producer bug — use SessionEvent::compacted with a positive count)"
334	                    );
335	                }
336	                if n > contributions.len() {
337	                    tracing::warn!(
338	                        original_count = n,
339	                        events_seen = contributions.len(),
340	                        "Compacted event references more events than have been seen; treating as 'compact everything observed so far' (likely corrupt log)"
341	                    );
342	                }
343	                let drop_from_idx = contributions.len().saturating_sub(n);
344	                let drop_msg_count: usize = contributions[drop_from_idx..].iter().sum();
345	                let new_len = messages.len() - drop_msg_count;
346	                messages.truncate(new_len);
347	                // Drop the contribution entries the Compacted event subsumed
348	                // so a subsequent Compacted's `n` indexes back over the
349	                // remaining events, not the already-summarized ones.
350	                contributions.truncate(drop_from_idx);
351	                messages.push(Item::System {
352	                    content: vec![ContentPart::Text {
353	                        text: summary.clone(),
354	                    }],
355	                });
356	                contributions.push(1);
357	            }
358	        }
359	    }
360	
361	    ConversationSnapshot { messages }
362	}
363	
364	/// Accumulates one run's semantic items as [`SessionEvent`]s for the runner to
365	/// persist at run exit.
366	///
367	/// The runner pre-seeds the recorder with the run's `AgentInput` messages (the
368	/// new turn — which the agent does not re-emit on its event stream), then feeds
369	/// it every [`crate::AgentEvent`] as the stream flows. [`SessionRecorder::drain`]
370	/// returns the accumulated log, synthesizing a [`SessionEvent::ToolReturned`]
371	/// for any tool call left without a result (a run interrupted mid-tool) so the
372	/// log always [`project`]s to a provider-valid conversation.
373	#[derive(Debug)]
374	pub struct SessionRecorder {
375	    events: Vec<SessionEvent>,
376	    current_agent: String,
377	}
378	
379	impl SessionRecorder {
380	    /// Create a recorder seeded with the root agent's name. Used to attribute
381	    /// assistant messages whose [`Item::AssistantMessage`] `agent` is `None`,
382	    /// before any `RunStarted`/`AgentUpdated` updates the tracked agent.
383	    pub fn new(root_agent: impl Into<String>) -> Self {
384	        Self {
385	            events: Vec::new(),
386	            current_agent: root_agent.into(),
387	        }
388	    }
389	
390	    /// Record the run's input messages (the new turn). The agent never re-emits
391	    /// these on its event stream, so the runner records them directly.
392	    /// [`Item::System`] has no [`SessionEvent`] equivalent and is skipped.
393	    pub fn record_input(&mut self, messages: &[Item]) {
394	        for item in messages {
395	            match item {
396	                Item::UserMessage { content } => {
397	                    self.events
398	                        .push(SessionEvent::user_message(content.clone()));
399	                }
400	                Item::AssistantMessage { content, agent } => {
401	                    let name = agent.clone().unwrap_or_else(|| self.current_agent.clone());
402	                    self.events
403	                        .push(SessionEvent::assistant_message(content.clone(), name));
404	                }
405	                Item::ToolCall {
406	                    call_id,
407	                    name,
408	                    args,
409	                } => {
410	                    self.events.push(SessionEvent::tool_called(
411	                        call_id.clone(),
412	                        name.clone(),
413	                        args.clone(),
414	                    ));
415	                }
416	                Item::ToolResult { call_id, content } => {
417	                    self.events.push(SessionEvent::tool_returned(
418	                        call_id.clone(),
419	                        content.clone(),
420	                    ));
421	                }
422	                Item::System { .. } => {
423	                    tracing::debug!(
424	                        "SessionRecorder: skipping Item::System in input (no SessionEvent variant)"
425	                    );
426	                }
427	            }
428	        }
429	    }
430	
431	    /// Observe one [`crate::AgentEvent`] from the run's stream: record the
432	    /// semantic items (assistant messages, tool calls, tool results, handoffs)
433	    /// and track the active agent from `RunStarted` / `AgentUpdated`.
434	    pub fn observe(&mut self, event: &AgentEvent) {
435	        match event {
436	            AgentEvent::RunStarted { agent } | AgentEvent::AgentUpdated { agent } => {
437	                self.current_agent = agent.clone();
438	            }
439	            AgentEvent::MessageOutput {
440	                item: Item::AssistantMessage { content, agent },
441	            } => {
442	                let name = agent.clone().unwrap_or_else(|| self.current_agent.clone());
443	                self.events
444	                    .push(SessionEvent::assistant_message(content.clone(), name));
445	            }
446	            AgentEvent::ToolCallItem {
447	                item:
448	                    Item::ToolCall {
449	                        call_id,
450	                        name,
451	                        args,
452	                    },
453	            } => {
454	                self.events.push(SessionEvent::tool_called(
455	                    call_id.clone(),
456	                    name.clone(),
457	                    args.clone(),
458	                ));
459	            }
460	            AgentEvent::ToolOutputItem {
461	                item: Item::ToolResult { call_id, content },
462	            } => {
463	                self.events.push(SessionEvent::tool_returned(
464	                    call_id.clone(),
465	                    content.clone(),
466	                ));
467	            }
468	            AgentEvent::HandoffItem { from, to } => {
469	                self.events
470	                    .push(SessionEvent::handoff_occurred(from.clone(), to.clone()));
471	            }
472	            _ => {}
473	        }
474	    }
475	
476	    /// Drain the accumulated events, appending a synthesized
477	    /// [`SessionEvent::ToolReturned`] for every [`SessionEvent::ToolCalled`]
478	    /// left without a matching result (a run cancelled/timed out mid-tool).
479	    /// The returned log always [`project`]s to a provider-valid conversation.
480	    pub fn drain(&mut self) -> Vec<SessionEvent> {
481	        let returned: std::collections::HashSet<String> = self
482	            .events
483	            .iter()
484	            .filter_map(|e| match e {
485	                SessionEvent::ToolReturned { call_id, .. } => Some(call_id.clone()),
486	                _ => None,
487	            })
488	            .collect();
489	        let mut synthesized = Vec::new();
490	        for e in &self.events {
491	            if let SessionEvent::ToolCalled { call_id, .. } = e {
492	                if !returned.contains(call_id) {
493	                    synthesized.push(SessionEvent::tool_returned(
494	                        call_id.clone(),
495	                        vec![ContentPart::Text {
496	                            text: "tool call did not complete (run cancelled/timed out)".to_owned(),
497	                        }],
498	                    ));
499	                }
500	            }
501	        }
502	        let mut out = std::mem::take(&mut self.events);
503	        out.extend(synthesized);
504	        out
505	    }
506	}
507	
508	/// Monotonic position in a [`Session`]'s append-only log.
509	#[derive(Debug, Clone, Copy, PartialEq, Eq, PartialOrd, Ord, Hash, Serialize, Deserialize)]
510	pub struct SequenceId(pub u64);
511	
512	/// A computed projection of a [`Session`]'s log into a single
513	/// conversation state. The `messages` field is the canonical view a
514	/// session emits.
515	#[derive(Debug, Clone, Default, Serialize, Deserialize)]
516	#[non_exhaustive]
517	pub struct ConversationSnapshot {
518	    /// Canonical message list, in conversational order.
519	    pub messages: Vec<Item>,
520	}
521	
522	/// Errors raised by [`Session`] methods.
523	#[derive(Debug, thiserror::Error)]
524	#[non_exhaustive]
525	pub enum SessionError {
526	    /// Backend unreachable (database down, file locked, …).
527	    #[error("session backend unavailable")]
528	    Unavailable,
529	
530	    /// A backend-specific error, type-erased so core stays free of any
531	    /// particular backend dependency. The `'static` bound is required for
532	    /// `<dyn Error>::downcast_ref` to work; callers who care about
533	    /// the underlying type can do `err.downcast_ref::<sqlx::Error>()`.
534	    #[error(transparent)]
535	    Backend(Box<dyn std::error::Error + Send + Sync + 'static>),
536	
537	    /// Escape hatch.
538	    #[error(transparent)]
539	    Other(#[from] anyhow::Error),
540	}
541	
542	impl SessionError {
543	    /// Wrap a backend-specific error as [`SessionError::Backend`].
544	    ///
545	    /// Saves the
546	    /// `.map_err(|e| SessionError::Backend(Box::new(e)))` boilerplate at
547	    /// every query call site — use as `.map_err(SessionError::backend)`.
548	    pub fn backend<E>(e: E) -> Self
549	    where
550	        E: std::error::Error + Send + Sync + 'static,
551	    {
552	        Self::Backend(Box::new(e))
553	    }
554	}
